toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product, CartLine } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("refreshPrices", () => {
  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 2 }];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.unitPriceCents).toBe(1500);
    expect(result[0].quantity).toBe(2);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-5),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    const lines: CartLine[] = [{ product: productA, quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("service down");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

describe("InventoryError", () => {
  it("has correct shape", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err).toBeInstanceOf(Error);
  });

  it("available can be undefined", () => {
    const err = new InventoryError("gone", "prod-2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 0 }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(0);
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("passes when inventory available and quantity sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("asyncTaxProvider with discount computes tax on discounted subtotal", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      region: "US",
    });
    cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // 10% of 800 = 80
    expect(result.totals.taxCents).toBe(80);
  });

  it("full pipeline: priceFetcher + discount + asyncTax + shipping", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) => {
        if (id === "a") return Promise.resolve(1200);
        return Promise.resolve(2500);
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal: 1200*2 + 2500*1 = 4900
    // discount: 10% of 4900 = 490
    // discounted: 4900 - 490 = 4410
    // tax: 8% of 4410 = 352.8 -> floor = 352
    // shipping: flat 500
    // total: 4410 + 352 + 500 = 5262
    expect(result.totals.subtotalCents).toBe(4900);
    expect(result.totals.discountCents).toBe(490);
    expect(result.totals.taxCents).toBe(352);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(5262);
  });

  it("propagates asyncTaxProvider error", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("first inventory denial wins when multiple items in cart", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation((id: string) => {
        if (id === "a") return Promise.resolve({ available: true });
        return Promise.resolve({
          available: false,
          reason: "discontinued",
        });
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("inventory check uses custom reason in error message", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "warehouse fire",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect((err as InventoryError).message).toBe("warehouse fire");
    }
  });
});

